      blocTrouve: '🎉🎉🎉 DIFFICULTÉ RÉSEAU ATTEINTE — BLOC POTENTIEL TROUVÉ !!! 🎉🎉🎉',
      souscription: (e1, sz) => `Souscription OK (extranonce1=${e1}, en2size=${sz})`,
