      calibPalier: (n, hr) => `   ${n} cores → ${hr} MH/s`,
      calibFin: (no, ho, nm, hm) => `✅ Best setting: ${no} cores (${ho} MH/s) · max ${nm} cores (${hm} MH/s)`,
